"Abstand Anfang / Ende":"מרחק מההתחלה / מהסוף",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"מרחק מההתחלה / מהסוף הופך את האוגן לאוגן חלקי. פרופילים סגורים נוספים בסקיצה הופכים לגזרות בלוח. קדחים וחלונות באוגן: מרכז לאורך הקצה (בקצה מעוגל – לאורך הקשת), מרכז מסוף הכיפוף, גודל – הם מופיעים גם בפריסה. כאשר קצה מעוגל עובר אל הקצה הסמוך לו ללא שבר, ולשניהם אוגן עם אותה זווית כיפוף, האוגנים נמשכים זה לתוך זה ללא חיתוך הפרשה. “קונטור מסקיצה” חותך את הפרופילים הסגורים של סקיצה מתוך האוגן: ציר X שלה עובר לאורך הקצה, ציר Y פנימה אל האוגן, ונקודת האפס נמצאת בתחילת הקצה על סוף הכיפוף (ניתנת להזזה).",
