"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"לאפס את כל ההעדפות, התאמות סרגל הכלים וקיצורי המקלדת האישיים לברירות המחדל?\n\nספריות כלים אישיות, חומרים ותבניות יישמרו.",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"יש לבחור את כל הפאות שאמורות להיעלם (בכיס – דפנות ותחתית, בקדח – הדופן, בעיגול פינות – העיגול). הפאות השכנות מורחבות מעבר לפער. השלב מחושב מחדש בעת שינויים בגוף; בפעם הראשונה נטענת לשם כך ליבת הגיאומטריה המלאה (כמה שניות).",
