"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"במצב „קדחים“ הראש יושב בצד הקדח הקרוב יותר לנקודת הלחיצה; הגוף פונה אל תוך הקדח. לחצו על כמה קדחים ברצף ואז על „סיום“.",
