"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"ניתן לגרור מידות והערות מותאמות בגיליון באמצעות העכבר (מרחק קו המידה, זווית קו ההפניה, רדיוס קשת הזווית). לחיצה על שתי פינות = מידת אורך. לחיצה על שפת מעגל במבט עליון = קוטר (או רדיוס). זווית: תחילה הקודקוד, ואז נקודה על כל אחד מהשוקיים. פאזה: שני קצוות הקצה המשופע – מתקבל למשל 2×45°. בשדה הטקסט שאחרי כל מידה מופיעה תוספת כמו ±0,1, H7 או 4×.",
