"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft דורש שתי סקיצות עם עקום אחד בכל אחת (על מישורים שונים).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"לא ניתן ליצור לופט – יש לבדוק את החתכים (פרופיל סגור אחד לכל חתך, ללא פיתול)",
