"Ersetzt den Standard-Kurzbefehl „{0}“.":"מחליף את קיצור ברירת המחדל “{0}”.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"יש ללחוץ תחילה על הפאה בגוף שיזוז, ואז על פאת היעד בגוף השני. הגוף מסובב ומוזז עד שנקודת הלחיצה הראשונה מונחת על השנייה והפאות מונחות זו על זו.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"יש ללחוץ תחילה על הקצה בגוף שיזוז, ואז על קצה היעד בגוף השני. קצוות ישרים נעים לחפיפה (אמצע על אמצע); בקצוות מעגליים – קדח וסיכה – הצירים מיושרים באותו כיוון והמרכזים מצטרפים.",
"Erst ein Setup anlegen.":"יש ליצור תחילה הגדרה.",
"Erst ein Setup mit Operationen anlegen.":"יש ליצור תחילה הגדרה עם פעולות.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"יש לבחור קודם סקיצה או מישור עזר – אז Ctrl+8 יציג מבט ניצב אליו.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"צרו תחילה גוף בתכנון או הוסיפו רשת (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"יש ליצור תחילה גוף בתכנון.",
"Erst einen Namen für das Profil eingeben.":"יש להזין קודם שם לפרופיל.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"יש ללחוץ תחילה בתוך תבנית ואז לבחור את משתנה המקום",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"לחצו על הפינה הראשונה ואז על הפינה הנגדית.",
