"Fläche am bewegten Körper gewählt":"נבחרה פאה בגוף הנע",
"Fläche anklicken – die Bohrung entsteht mit":"לחצו על פאה – החור נוצר יחד עם זה",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"לחצו על פאה: בכל נקודת לחיצה נוצר חור מעבר לבורג (ISO 273, סדרה בינונית) דרך כל החלקים הנמצאים שם זה על זה – לברגים שקועים עם שיקוע קוני של 90°, ולברגים גליליים לפי בחירה עם חור שקוע (DIN 974-1, סדרה 1) בעומק הראש. הבורג מונח בו מיד. אפשר לשנות את החור והבורג לאחר מכן בציר הזמן.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"לחצו על פאה של גוף: גבולה מתווסף לסקיצה כקונטור. לחיצה על קצה מטילה רק אותו (מעגלים נשארים מעגלים). גיאומטריה מוטלת מוצגת בסגול.",
"Fläche ersetzen":"החלפת פאה",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"החלפת פאה: העברת פאה שטוחה למישור אחר – הגוף גדל או מתקצר",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"השטח שמאחורי החלונות – חל כאשר נבחר למעלה העיצוב „אישי“",
"Fläche löschen":"מחיקת פאה",
