"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"הצגת הפאה או הקצה מתחת לסמן העכבר בצבע",
"Fläche versetzen":"הסטת פאה",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"הסטת פאה: הזזת פאות שטוחות ושינוי קוטר של קדחים וסיכות בולטות",
"Fläche wählen":"בחרו פאה",
