"Flächen am Körper":"פאות הגוף",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"פאות שטוחות בקצה החלק (דו-שטוח, מרובע, משושה) בכרסם קצה מונע לאורך Z. מפתח = כפול המרחק של הפאה מציר הסיבוב. X ו-C נעים יחד (אינטרפולציה קוטבית, Fanuc G12.1); ללא תבנית זו בפוסט-פרוססור מופקים צעדי X/C קצרים.",
