"Gemeinsame Schnittkanten nur einmal schneiden":"חיתוך קצוות משותפים פעם אחת בלבד",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"קצוות חיתוך משותפים: אם שני חיתוכים נמצאים במרחק של רוחב חתך אחד בדיוק זה מזה (בפריסה יש להזין את רוחב החתך כמרחק), המסלול שלהם חופף על הקצה המשותף והוא נחתך פעם אחת בלבד. הכניסה לחיתוך אינה נמצאת לעולם בחלק סמוך: אם אין ליד קונטור פסולת פנויה, הניקוב מתבצע על הקונטור. לאחר “תצוגה מקדימה” תמונה לכל לוח מציגה את המסלול לפני שמירת הקבצים.",
