"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"קווים ישרים בסקיצה שאינם שייכים לאף פרופיל (גם קווי עזר). כיפוף: הקו הוא אמצע אזור הכיפוף, והסקיצה שם היא החיתוך – החלק הגדול ביותר של הלוח נשאר במקומו, וכל מה שמעבר לקו מסתובב יחד עם האוגנים שלו. הקו חל על פני הלוח כולו. ריב חיזוק: צלע לאורך הקו, עגולה בחתך ובקצותיה; הפח שומר על עוביו.",
