"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"סגור: לשוניות בשני קצוות סמוכים מגיעות עד חוצה הזווית של הפינה ומשאירות שם את המרווח. ההקלה בפינה ממוקמת במקום שבו אזורי הכיפוף נחתכים – בפריסה ובחלק המכופף. גם אוגן בקצה מעוגל נחתך בזווית (גרונג) בפינה אמיתית (שם ללא הקלה בפינה).",
