"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"בתמונת המראה הכלי נע בכיוון ההפוך: כרסום עם כיוון הסיבוב הופך שם לכרסום נגד כיוון הסיבוב. גם פיצוי הרדיוס של הבקר מחליף צד.",
