"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"גופים מיובאים הם ללא היסטוריית תכנון, אך אפשר להמשיך לערוך אותם (עיגול פינות, פאזה, חיתוך …) ולהשתמש בהם ב-CAM. עם „ציר Y כלפי מעלה“ מודלים מתוכנות שבהן Y פונה כלפי מעלה מוצבים נכון.",
