"J (relativ)":"J (יחסי)",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"העקומה הראשונה בכל סקיצה – פתוחה או סגורה. העקומות מחוברות בעור (משטח ללא עובי).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"קובץ אחד לכל לוח. המסלול עובר לצד קו המתאר בתוך הפסולת במרחק חצי רוחב החתך (בכרסום – חצי כרסום); גזרות באות לפני קו המתאר של החלק שלהן, וכל קונטור מתחיל בכניסה לחיתוך מתוך הפסולת. חריצי תריסי האוורור נחתכים על הקו שלהם. גשרי החזקה: כמות זו של מקומות לכל קו מתאר נשארת ללא חיתוך (לייזר, פלזמה, סילון מים: הקרן מפסיקה שם; כרסום: הכרסום עולה לחצי עובי הפח), קווי מתאר באורך מתחת ל-40 mm לא מקבלים גשרים. „בקר“ קובע כיצד הקרן מופעלת ומכובה; זמן הניקוב מופיע בתוכנית כ-G4, אלא אם הבקר מנקב בעצמו. נקודת האפס היא הפינה השמאלית התחתונה של הלוח, ובכרסום Z0 הוא פני הפח העליונים. יש לבדוק את התוכנית לפני השימוש במכונה או בסימולטור NC.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"כל ציר בנפרד: לחץ על קצה, פינה, פאה או קדח. צירים שלא הוגדרו נלקחים מנקודת חומר הגלם.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"כל פעולה כתת-תוכנית (LBL) בסוף התוכנית, הקריאה באמצעות CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"כל מעגל בסקיצה הוא מרכז קדח. הקידוח מתבצע נגד הנורמל של הסקיצה (לתוך החומר).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"כל מעגל בסקיצה חוזר בסיבוב סביב המרכז (בקואורדינטות הסקיצה) – מעגל במרחק רדיוס מעגל החלוקה יוצר מעגל קדחים.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"כל מעגל בסקיצה הופך לרשת: מרחקים ב-X וב-Y של הסקיצה (גם שליליים).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"כעת נקודה על השוק השני.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"כעת הזיזו כל כיוון פעם אחת עד הקצה: דחיפה, משיכה, לחיצה, הטיה, סיבוב (10 s) …",
"Jetzt laden":"הורדה עכשיו",
"Jetzt nach Updates suchen":"חיפוש עדכונים כעת",
"K-Faktor":"מקדם K",
"K-Faktor {0} liegt außerhalb des üblichen Bereichs 0,25 … 0,5 – der Zuschnitt weicht dann meist vom gebogenen Teil ab.":"מקדם K {0} מחוץ לטווח הרגיל 0,25 … 0,5 – אז החיתוך יסטה בדרך כלל מהחלק המכופף.",
