"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"כיול: יש ללחוץ על הנקודה הראשונה בתמונה (Esc מבטל).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"כיול: המרחק האמיתי בין שתי הנקודות (מ\"מ)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"כיול: יש ללחוץ על שתי נקודות בתמונה שהמרחק ביניהן ידוע ולהזין את המרחק האמיתי – התמונה תקבל את קנה המידה הנכון.",
