"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"הקונטורים עוקבים אחר שפת השטחים הכהים. קו האמצע עובר באמצע הקווים – מתאים לחריטות ולשרטוטי קווים. „קווים ישרים, קשתות ומעגלים“ מזהה קצוות ישרים, פינות חדות, עיגולים ומעגלים; „פוליליין“ עוקב אחר התמונה נקודה אחר נקודה. את קנה המידה אפשר להתאים לאחר מכן לפי הצורך בעזרת „כיול תבנית“ או „שינוי קנה מידה“.",
