"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"עקומות של סקיצה על הפנים המישוריים (בניצב לציר הסיבוב) בכרסם מונע לאורך Z (X ו-C נעים יחד; Fanuc: אינטרפולציה קוטבית G12.1). עקומות פתוחות מכורסמות הלוך וחזור. העומק מהפנים המישוריים.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"עקומות של סקיצה המונחת לאורך ציר הסיבוב נכרכות על ההיקף ומכורסמות בכרסם מונע המכוון אל הציר (Z ו-C נעים יחד; Fanuc: אינטרפולציה גלילית G7.1). מישור הסקיצה קובע את הזווית שבה יושב הקונטור; קטעים אופקיים בסקיצה הופכים לקשתות סביב החלק. העומק מהקוטר החיצוני.",
"Kurzbefehl":"קיצור",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"מסלולים קצרים (עד מרחק ההשארה) הכלי עובר למטה בקצב ההזנה של המעבר במקום דרך גובה הנסיגה – ללא בדיקת התנגשות, ולכן יש לשמור על ערך קטן.",
