"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"יש לבחור את החומר בהגדרה תחת “חומר גלם ← חומר של חומר הגלם”. הצפיפות קובעת את משקל חומר הגלם, Vc הוא ערך מנחה לקרביד; הצבע מוצג בסימולציה.",
