"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"מספר קצוות מחוברים נחשבים כמסלול אחד: הרדיוס נע מתחילת השרשרת ועד סופה, נקודות הבקרה נתונות ב-% מאורך השרשרת כולה. החישוב מתבצע על ידי ליבת הגיאומטריה המלאה.",
