"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"עם נקודות בקרה הרדיוס עובר דרך הערכים שצוינו (מיקום ב-% מאורך הקצה). החישוב מתבצע על ידי ליבת הגיאומטריה המלאה; בפעם הראשונה הטעינה אורכת כמה שניות.",
"Mit dem 3D-Taster kann nicht zerspant werden":"לא ניתן לחתוך עם גשש תלת-ממדי",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"השוואה לחלק המוגמר: ירוק = במידה, כחול = חומר שנותר, אדום = עמוק מדי",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"העברת העכבר ליד קונטור (הצד קובע את הכיוון) · Esc לסיום",
"Mit diesem Werkzeug kann nicht gefräst werden":"לא ניתן לכרסם עם כלי זה",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"עם ברז הברגה יש להשתמש רק במחזור “הברגה בברז” – מחזור קידוח ישבור אותו",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"עם מספר הזנות עומק התבריג מכורסם בשלבים שכל אחד מהם מסיר כמות דומה – עדין יותר לכלי הברגה קטנים ולחומרים קשים. המעבר הריק חוזר על המסלול האחרון פעם נוספת ללא הזנה.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"עם “מחזורי קידוח” בתוכנית ה-NC מופקים מחזורי בקר (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), אחרת מופקות תנועות מפורטות.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"עם “שמירת המקור” המקור והשיקוף שלו הופכים לרשת אחת; נקודות על מישור השיקוף מחוברות – כך חצי פתוח הופך לחלק סגור.",
