"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"אין עדיין גוף – יש למדל תחילה בתכנון.",
"Noch keine Designs gespeichert.":"טרם נשמרו עיצובים.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"אין הערות עדיין. השתמשו ב-+ כדי לרשום הערות על העיצוב.",
"Noch keine Operation":"אין עדיין פעולה",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"אין עדיין תבניות. תבנית שומרת אסטרטגיות על כל הגדרותיהן (כלי, נתוני חיתוך, גבהים, מעברים, קישור) לשימוש חוזר בהגדרות ובתכנונים אחרים.",
"Noch keine Werkzeuge im Dokument.":"עדיין אין כלים במסמך.",
