"Nur Außenkonturen":"קונטורים חיצוניים בלבד",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"רק קונטורים חיצוניים (בליטות) נתמכים כמחזור בקרה",
"Nur Durchmesser (Form wie dieses Werkzeug)":"קוטר בלבד (צורה כמו כלי זה)",
"Nur Innenkonturen (Öffnungen)":"קונטורים פנימיים בלבד (פתחים)",
