"Nur Skizze":"סקיצה בלבד",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"עיבוד רק של מה שכרסום גדול יותר השאיר בפינות.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"מעקב רק אחר חלקי הקונטור שכרסום גדול יותר לא הגיע אליהם (פינות פנימיות, אזורים צרים). ללא קשתות כניסה/יציאה, גשרי החזקה ומעברי גימור; פיצוי במחשב.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"רק במקומות שכלי הייחוס לא הגיע אליהם: אזורים שטוחים במקביל, אזורים תלולים כקו מים. עם כלי מהרשימה נלקחת בחשבון גם צורתו – למשל מה שכרסם טורוס (קצה מעוגל) משאיר בחריצים הקעורים.",
"Nur ebene Flächen können als Skizzenebene dienen.":"רק פאות שטוחות יכולות לשמש כמישור סקיצה.",
"Nur ebene Flächen können extrudiert werden":"ניתן לשחל רק פאות שטוחות",
"Nur ebene Flächen lassen sich ersetzen":"ניתן להחליף רק פאות שטוחות",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"ניתן להזיז רק פאות שטוחות וגליליות (קדחים, תמוכות)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"רק פאות שטוחות הפונות כלפי מעלה אל הכלי (אופקיות בהגדרה הנוכחית).",
"Nur für Außen-Drehmeißel":"לכלי חריטה חיצוניים בלבד",
"Nur in Operationen verwendete":"רק כאלה שבשימוש בפעולות",
"Nur in diesem Projekt":"בפרויקט זה בלבד",
"Nur mit Korrektur „Im Rechner“.":"רק עם פיצוי “במחשב”.",
"Nur stärkste Achse":"הציר החזק ביותר בלבד",
"Nut":"חריץ",
"Nut angetrieben":"חריץ בכלי מונע",
"Nut angetrieben (C-Achse)":"חריץ בכלי מונע (ציר C)",
"Nut liegt nicht am Teil":"החריץ אינו על החלק",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"חריץ לאורך ציר הסיבוב (למשל חריץ מפתח) בכרסם מונע המכוון אל הציר; הציר הראשי מחזיק את החלק כציר C. רוחב חריץ = קוטר כרסם Ø. התחלה/סוף Z ב-Z של המודל; אם החריץ מגיע אל הפנים המישוריים הכרסם נכנס מקדימה, אחרת הוא צולל בנקודת ההתחלה. העומק מהקוטר החיצוני.",
"Nutbreite bei Linien":"רוחב חריץ בקווים",
"Nuten":"חריצים",
"Nutenfräser":"כרסום חריצים",
"Nuttiefe":"עומק החריץ",
"Nuttiefe angeben":"יש לציין עומק חריץ",
"Nuttiefe {0} mm ist größer als der Radius {1} mm":"עומק החריץ {0} מ״מ גדול מהרדיוס {1} מ״מ",
"Nächstes Werkzeug schon vorbereiten (TOOL DEF bzw. T-Wort)":"הכנת הכלי הבא מראש (TOOL DEF או מילת T)",
"O-Ring (ISO 3601)":"טבעת O (ISO 3601)",
"OBEN":"עליון",
"OK":"אישור",
"Oben":"עליון",
"Oben (Z+ nach oben)":"עליון (Z+ כלפי מעלה)",
"Oben auf FERTIGUNG wechseln für CAM.":"עברו למעלה אל ייצור עבור CAM.",
"Obere Höhe":"גובה עליון",
"Oberer Ø":"Ø עליון",
"Oberfläche":"שטח פנים",
"Oberfläche Z":"משטח עליון Z",
"Oberflächenzeichen hinzufügen":"הוספת סימן גימור פני שטח",
"Oberflächenzeichen und Bezüge bitte in der Vorder-, Drauf- oder Seitenansicht setzen.":"נא להציב סימני גימור פני שטח וייחוסים במבט הקדמי, העליון או הצדדי.",
"Oberhalb / Plusseite":"מעל / הצד החיובי",
"Oberseite des Rechtecks bzw. Taschenboden":"הפאה העליונה של המלבן או תחתית הכיס",
"Oder Skizze":"או סקיצה",
"Offen (Laschen gekürzt)":"פתוח (לשוניות מקוצרות)",
"Offene Flächen":"פאות פתוחות",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"קצוות פתוחים מוצגים באדום. „תיקון“ סוגר חורים.",
"Offene Linie in einer Skizze wählen":"יש לבחור קו פתוח בסקיצה",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"עקומות פתוחות או סגורות נמשכות בניצב לסקיצה – נוצר משטח (דופן ללא עובי). עם „עיבוי“ או „תפירה“ הוא הופך לנפח.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"עקומות פתוחות או סגורות מסובבות סביב הציר – נוצר משטח, לא נפח.",
