"Tasche Planfläche (C-Achse)":"כיס על פני החזית (ציר C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"כיס על ההיקף מתוך הקונטורים הסגורים של סקיצה המונחת לאורך ציר הסיבוב (קונטורים פנימיים נשארים כאיים). הסקיצה נכרכת על הקוטר; כרסום קצה שטוח מונע המכוון אל הציר מרוקן מבפנים החוצה (Z ו-C נעים יחד; ב-Fanuc: אינטרפולציה גלילית G7.1). הכרסום חודר ברמפה לאורך הטבעת הפנימית ביותר.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"כיס בפנים המישוריים מהקונטורים הסגורים של סקיצה (קונטורים פנימיים נשארים כאיים), עם כרסום קצה מונע לאורך Z. הפינוי מתבצע מבפנים החוצה; הכרסם צולל על רמפה לאורך המסלול הפנימי ביותר ונשאר למטה בתוך מישור אחד. X ו-C נעים יחד (Fanuc: אינטרפולציה קוטבית G12.1). העומק מהפנים המישוריים.",
