"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"מבצע פעולה אמיתית בין שתי רשתות סגורות: פאות פנימיות נעלמות וקצוות החיתוך נרשתים מחדש. החישוב מתבצע רק במקום שבו שתי הרשתות יכולות להיפגש – לכן רשת גדולה עם התערבות קטנה מהירה. אם שתי רשתות גדולות חופפות לגמרי, יש להפעיל קודם “הקטנה”.",
