"{0}: Fläche oder Kante im Modell anklicken.":"{0}: לחץ על פאה או קצה במודל.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0}: GRBL אינו תומך בפיצוי רדיוס כלי (G41/G42) – המסלול הופק ללא פיצוי",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0}: נקודת האפס Y/Z אינה על ציר הסיבוב A (הציר ב-Y{1} Z{2}) – לעיבוד סימולטני ב-4 צירים יש להניח את נקודת האפס על הציר (נקודת חומר הגלם: מרכז Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0}: פוסט-פרוססור ללא מחזור חריטה – הופק כמסלול",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0}: פוסט-פרוססור ללא אינטרפולציה קוטבית – פאות הופקו כצעדי X/C קצרים (C במעלות); קצב ההזנה אז, בהתאם לבקר, אינו חל לאורך המסלול. עדיף למלא את התבנית „אינטרפולציה קוטבית פעילה/כבויה“",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: פוסט-פרוססור ללא תבנית \"הפעלת ציר C וכלי מונע\" – יש להפעיל ידנית את ציר C ואת ציר הכלי",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0}: פוסט-פרוססור ללא אינטרפולציה גלילית – Z ו-C נעים יחד; קצב ההזנה אז, בהתאם לבקר, אינו חל לאורך המסלול. עדיף למלא את התבנית „אינטרפולציה גלילית פעילה/כבויה“",
"{0}: Postprozessor ohne {1} für diese Form – als Bahn ausgegeben":"{0}: פוסט-פרוססור ללא {1} לצורה זו – הופק כמסלול",
"{0}: Schlichtzyklus folgt der Hüllkontur – Hinterschnitt/Einstich bleibt stehen":"{0}: מחזור הגימור עוקב אחר קונטור המעטפת – תחתית/חריץ נשארים",
"{0}: Schlichtzyklus fährt die Fertigkontur – Aufmaß {1} mm wird nicht berücksichtigt":"{0}: מחזור הגימור עוקב אחר הקונטור הסופי – תוספת החומר {1} מ״מ אינה נלקחת בחשבון",
