"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"“שיבוץ זה בתוך זה” מניח את החיתוכים ברווחים ובמפרצים של שכניהם ובגזרות שלהם (ללא סיבוב של 90° – רק הפיכה של 180°); המרחק שנקבע לעולם אינו קטן יותר. ללא הסימון הם מונחים בשורות לפי המלבן התוחם שלהם. עם “סקיצה + גופים” נוצרים גופים שטוחים בעובי הפח, שאפשר לחתוך בייצור עם קונטור דו-ממדי.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"“פנים/חוץ” דורש קונטורים סגורים – כרסמו עקומים פתוחים באפשרות “על העקום”",
